"use client";
import {useState} from "react";
import type {vendorWorkspace,vendorDetail} from "../../../lib/server/vendor-service";
import {VENDOR_CRITERIA,requiredVendorCriteria,vendorAssessmentIssues,vendorReviewSchema} from "../../../lib/assurance-workflows";
import type {z} from "zod";
import AuditSession,{auditRequest,date,type Context,type Serial} from "../audits/audit-session";
import {useRecordWorkspace,day} from "../workflow-ui";
import ui from "../operations/operations.module.css";
import styles from "../audits/audits.module.css";
type Overview=Serial<Awaited<ReturnType<typeof vendorWorkspace>>>;
type Detail=Serial<Awaited<ReturnType<typeof vendorDetail>>>;
type Assessment=z.infer<typeof vendorReviewSchema>["assessment"];
export default function Vendors(){return <AuditSession section="vendors">{ctx=><Home ctx={ctx}/>}</AuditSession>;}
function Home({ctx}:{ctx:Context}){
 const orgs=ctx.organisations.filter(o=>["OWNER","ADMIN"].includes(o.role)),[orgId,setOrgId]=useState(orgs[0]?.id||"");
 return <><section className={ui.toolbar}><label>Organisation<select value={orgId} onChange={e=>setOrgId(e.target.value)}>{orgs.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label><a href="/team/operations">Back to operations</a></section>{orgId?<Workspace key={orgId} orgId={orgId} userId={ctx.userId||""}/>:<section className={ui.empty}><h2>Administrator access needed</h2><p>An owner or administrator records suppliers and approves their reviews.</p></section>}</>;
}
function VendorForm({members,value,busy,save}:{members:Overview["members"];value?:Detail["vendor"];busy:boolean;save:(d:Record<string,unknown>)=>void}){
 return <form onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);save({name:fd.get("name"),service:fd.get("service"),ownerId:fd.get("ownerId"),criticality:fd.get("criticality"),dataAccess:fd.get("dataAccess"),systemAccess:fd.get("systemAccess")==="on",nextReview:fd.get("nextReview")});}}>
 <fieldset disabled={busy} className={styles.fieldset}><div className={ui.formGrid}>
 <label>Supplier name<input name="name" required minLength={3} maxLength={160} defaultValue={value?.name} placeholder="Example IT Services"/></label>
 <label>Responsible colleague<select name="ownerId" required defaultValue={value?.ownerId||""}><option value="" disabled>Choose an owner</option>{members.map(m=><option key={m.user.id} value={m.user.id}>{m.user.email}</option>)}</select></label>
 <label className={ui.full}>What do they do for your business?<textarea name="service" required minLength={20} maxLength={1200} defaultValue={value?.service} rows={3} placeholder="Describe the service, information handled and important dependencies."/></label>
 <label>Business impact if unavailable<select name="criticality" defaultValue={value?.criticality||"MEDIUM"}><option value="LOW">Low — easy to replace</option><option value="MEDIUM">Medium — operations disrupted</option><option value="HIGH">High — essential service</option></select></label>
 <label>Information they handle<select name="dataAccess" defaultValue={value?.dataAccess||"BUSINESS"}><option value="NONE">No business information</option><option value="BUSINESS">Business information</option><option value="PERSONAL">Personal information</option><option value="SENSITIVE">Sensitive information</option></select></label>
 <label>Next review date<input type="date" name="nextReview" required min={day()} max={day(366)} defaultValue={value?.nextReviewAt.slice(0,10)||day(30)}/></label>
 <label className={ui.check}><input type="checkbox" name="systemAccess" defaultChecked={value?.systemAccess}/>They can access our systems</label>
 </div><button>{value?"Save scope and ownership":"Add supplier"}</button></fieldset></form>;
}
function Workspace({orgId,userId}:{orgId:string;userId:string}){
 const w=useRecordWorkspace<Overview,Detail>("vendors",orgId),[search,setSearch]=useState(""),[attentionOnly,setAttentionOnly]=useState(true);
 return <>{w.notice&&<p role="status" className={ui.warning}>{w.notice}</p>}<ol className={styles.steps}><li><strong>1 · Record the service</strong><span>Scope, information, impact and owner</span></li><li><strong>2 · Check the evidence</strong><span>Six practical areas with explicit findings</span></li><li><strong>3 · Decide and follow up</strong><span>Independent sign-off and owned tasks</span></li></ol><p className={ui.hint}>Review supplier evidence alongside selected public register signals. These are review prompts, not certification, a complete legal assessment or a credit score.</p>
 {!w.data?<p role="status">Loading supplier workspace…</p>:<><section className={ui.card}><details open={!w.data.vendors.length}><summary>Add a supplier</summary><VendorForm members={w.data.members} busy={w.busy} save={d=>void w.mutate(d,"create")}/></details></section>
 <section className={ui.card}><div className={ui.toolbar}><h2>Supplier attention queue</h2><label className={ui.check}><input type="checkbox" checked={attentionOnly} onChange={e=>setAttentionOnly(e.target.checked)}/>Show only suppliers needing action</label><label>Find supplier<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name"/></label></div><div className={styles.rooms}>{w.data.vendors.filter(v=>(!attentionOnly||v.attention.needed)&&v.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(b.criticality==="HIGH")-Number(a.criticality==="HIGH")||a.nextReviewAt.localeCompare(b.nextReviewAt)).map(v=><button key={v.id} disabled={w.busy} aria-pressed={w.selected===v.id} onClick={()=>void w.open(v.id)}><strong>{v.name}</strong><span>{v.attention.label}</span><small>{v.attention.next}</small><span>{v.reviewState.replaceAll("_"," ")}{v.recommendation?" · "+v.recommendation:""}</span><small>{v.criticality} impact · {v.owner.email}<br/>Review {v.nextReviewAt.slice(0,10)}{v.active&&v.nextReviewAt.slice(0,10)<day()?" · OVERDUE":""}</small></button>)}</div>{!w.data.vendors.length&&<p>Add your first supplier above.</p>}{w.data.vendors.length>0&&!w.data.vendors.some(v=>(!attentionOnly||v.attention.needed)&&v.name.toLowerCase().includes(search.toLowerCase()))&&<p>No suppliers match this view. Clear the filter to inspect current reviews and archived history.</p>}</section>
 {w.detail&&<VendorRecord key={w.detail.vendor.id+":"+w.detail.vendor.version+":"+(w.detail.signal?.snapshot?.runId||"")+":"+w.detail.signal?.current+":"+w.detail.reviews.map(r=>r.id+r.version).join(":")} orgId={orgId} detail={w.detail} data={w.data} userId={userId} busy={w.busy} save={d=>void w.mutate(d)} prepare={d=>void w.mutate(d,"review")}/>}</>}</>;
}
function ReviewForm({vendor,evidence,busy,signal,save}:{signal:Detail["signal"];vendor:Detail["vendor"];evidence:Overview["evidence"];busy:boolean;save:(d:Record<string,unknown>)=>void}){
 const [files,setFiles]=useState<string[]>([]),[checks,setChecks]=useState<Assessment>(VENDOR_CRITERIA.map(c=>({id:c.id,outcome:"GAP",rationale:"",evidenceIds:[]}))),[message,setMessage]=useState("");
 const required=requiredVendorCriteria(vendor);
 function patch(index:number,change:Partial<Assessment[number]>){setChecks(v=>v.map((c,i)=>i===index?{...c,...change}:c));}
 function selectFile(id:string,selected:boolean){
  if(selected){setFiles(v=>[...v,id]);return;}
  setFiles(v=>v.filter(value=>value!==id));
  setChecks(v=>v.map(c=>({...c,evidenceIds:c.evidenceIds.filter(value=>value!==id)})));
 }
 return <form onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget);
  const parsed=vendorReviewSchema.safeParse({...(signal?{signalRunId:signal.snapshot?.runId,signalReviewed:fd.get("signalReviewed")==="on"}:{}),version:vendor.version,evidenceIds:files,assessment:checks,recommendation:fd.get("recommendation"),rationale:fd.get("rationale"),followUpDue:fd.get("followUpDue"),validUntil:fd.get("validUntil")});
  if(!parsed.success){setMessage("Complete every finding and explanation before preparing the review.");return;}
  const issues=vendorAssessmentIssues(vendor,parsed.data);if(issues.length){setMessage(issues.join(". "));return;}setMessage("");save(parsed.data);
 }}><fieldset disabled={busy} className={styles.fieldset}>
 <h3>Select supporting evidence</h3><p>Choose up to ten independently approved files, then reference the relevant files in each finding.</p><div className={ui.fileGrid}>{evidence.map(f=><label key={f.id}><input type="checkbox" checked={files.includes(f.id)} disabled={!files.includes(f.id)&&files.length>=10} onChange={e=>selectFile(f.id,e.target.checked)}/><strong>{f.filename}</strong></label>)}</div>{!evidence.length&&<p>Upload and approve supporting documents in the <a href="/team/evidence">evidence vault</a>. You can still record evidence gaps.</p>}
 {VENDOR_CRITERIA.map((c,index)=><section className={ui.review} key={c.id}><h3>{index+1}. {c.label}</h3><p>{c.help} {required.has(c.id)?"Required for this supplier scope.":"Explain if this does not apply."}</p><div className={ui.formGrid}><label>Finding<select value={checks[index].outcome} onChange={e=>patch(index,{outcome:e.target.value as Assessment[number]["outcome"]})}><option value="GAP">Gap or insufficient evidence</option><option value="SUPPORTED">Supported by evidence</option>{!required.has(c.id)&&<option value="NOT_APPLICABLE">Not applicable</option>}</select></label><label>Explain your finding<textarea required minLength={20} maxLength={1000} value={checks[index].rationale} onChange={e=>patch(index,{rationale:e.target.value})} rows={3}/></label></div>{files.length>0&&<><p className={ui.hint}>Evidence supporting this finding:</p><div className={ui.fileGrid}>{evidence.filter(f=>files.includes(f.id)).map(f=><label key={f.id}><input type="checkbox" checked={checks[index].evidenceIds.includes(f.id)} onChange={e=>patch(index,{evidenceIds:e.target.checked?[...checks[index].evidenceIds,f.id]:checks[index].evidenceIds.filter(id=>id!==f.id)})}/><strong>{f.filename}</strong></label>)}</div></>}</section>)}
 <div className={ui.formGrid}><label>Recommended decision<select name="recommendation" defaultValue="CONDITIONAL"><option value="APPROVE">Approve — no recorded gaps</option><option value="CONDITIONAL">Conditional — follow-up required</option><option value="REJECT">Reject — next steps required</option></select></label><label>Follow-up due<input name="followUpDue" type="date" required min={day()} max={day(366)} defaultValue={day(14)}/></label><label>Review valid until<input name="validUntil" type="date" required min={day()} max={day(366)} defaultValue={day(90)}/></label><label className={ui.full}>Reason for recommendation<textarea name="rationale" required minLength={40} maxLength={2000} rows={3}/></label></div>
 {signal&&<label className={ui.check}><input type="checkbox" required name="signalReviewed"/>I checked the exact company number and latest register indicators shown above, and explained warnings or unknowns in my recommendation.</label>}
 {message&&<p role="alert" className={ui.warning}>{message}</p>}<button>Prepare for independent review</button><p className={ui.hint}>Preparing a review does not approve this supplier or create tasks. A different administrator must sign it off.</p></fieldset></form>;
}
function Decision({review:r,userId,busy,save}:{review:Detail["reviews"][number];userId:string;busy:boolean;save:(d:Record<string,unknown>)=>void}){
 const [notes,setNotes]=useState(""),[confirmed,setConfirmed]=useState(false);
 const canAccept=r.createdById!==userId&&!r.files.some(f=>f.uploadedById===userId)&&r.contextCurrent;
 return <div className={ui.review}><h3>Independent decision</h3>{!canAccept&&<p className={ui.warning}>Approval needs a different administrator, current evidence and unchanged supplier scope. A competing accepted review also requires a new draft.</p>}<div className={ui.formGrid}><label>Review notes<textarea minLength={40} maxLength={2000} value={notes} onChange={e=>setNotes(e.target.value)} rows={3} disabled={busy}/></label></div><label className={ui.check}><input type="checkbox" checked={confirmed} disabled={busy||!canAccept} onChange={e=>setConfirmed(e.target.checked)}/>I checked these findings, evidence and the proposed decision.</label><div className={ui.buttons}><button disabled={busy||!canAccept||!confirmed||notes.trim().length<40} onClick={()=>save({action:"ACCEPT",reviewId:r.id,version:r.version,notes,confirm:true})}>Sign off {r.recommendation.toLowerCase()} decision</button><button disabled={busy||r.createdById===userId||notes.trim().length<20} onClick={()=>save({action:"RETURN",reviewId:r.id,version:r.version,notes})}>Return for changes</button></div></div>;
}
function VendorRecord({orgId,detail:d,data,userId,busy,save,prepare}:{orgId:string;detail:Detail;data:Overview;userId:string;busy:boolean;save:(d:Record<string,unknown>)=>void;prepare:(d:Record<string,unknown>)=>void}){
 const v=d.vendor,[archive,setArchive]=useState(false),[exporting,setExporting]=useState(false),[exportError,setExportError]=useState("");
 async function download(){setExporting(true);setExportError("");try{const value=await auditRequest("/api/workspace/vendors/"+v.id+"/export?organizationId="+encodeURIComponent(orgId));const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="regpilot-supplier-review.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){setExportError(e instanceof Error?e.message:"Export unavailable");}finally{setExporting(false);}}

 return <section className={ui.card}><span className={ui.eyebrow}>{d.reviewState.replaceAll("_"," ")}</span><h2>{v.name}</h2><button disabled={busy||exporting||d.reviewState!=="CURRENT"} onClick={()=>void download()}>{exporting?"Verifying evidence…":"Download current review record"}</button><p className={ui.hint}>Includes findings, evidence hashes, the reviewed register observation and condition tasks. Supporting files stay in the vault.</p>{exportError&&<p role="alert">{exportError}</p>}<p className={styles.prose}>{v.service}</p><p>Owner: {v.owner.email} · {v.criticality} impact · {v.dataAccess} information · {v.systemAccess?"System access":"No system access recorded"}</p>
 <div className={ui.review}><h3>{d.attention.label}</h3><p>{d.attention.next}</p>{v.active&&d.signal&&d.reviewState!=="CURRENT"&&<button disabled={busy} onClick={()=>save({action:"FOLLOW_UP",version:v.version})}>Assign review follow-up to {v.owner.email}</button>}<p className={ui.hint}>This records work without calling a connected provider. Existing open follow-up is reused.</p></div>
 {["STALE","EXPIRED"].includes(d.reviewState)&&<p className={ui.warning}>The previous decision needs a new review. Check current scope and evidence before relying on it.</p>}
 <section className={ui.review}><h3>Connected company-register monitoring</h3>{d.signalChanges.length>0&&<><h4>Changes since the accepted review</h4><p>{d.signal?.current?"Compare these findings before preparing the next review.":"Historical comparison: refresh collection before relying on these findings."}</p><ul>{d.signalChanges.map(c=><li key={c.id}><strong>{c.label}</strong><br/>Reviewed: {c.before}<br/>Latest recorded: {c.after}</li>)}</ul></>}{d.signal?<><p>{d.signal.companyNumber} · {d.signal.reason}</p>{d.signal.snapshot&&<><p>Observed {date(d.signal.snapshot.capturedAt)} · <a href={d.signal.snapshot.observation.sourceUrl} target="_blank" rel="noreferrer">Check the official register ↗</a></p><ul>{d.signal.snapshot.observation.checks.map(c=><li key={c.id}><strong>{c.label}</strong>: {c.observed} · {c.status}</li>)}</ul><p className={ui.hint}>These indicators do not establish financial health. An unavailable or changed observation makes dependent reviews stale.</p></>}</>:<p>No public register connection linked. <a href="/team/operations">Prepare a Companies House connection in Operations</a>, then link it here.</p>}{v.active&&<details><summary>Link or remove a register connection</summary><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);save({action:"LINK_SIGNAL",version:v.version,connectorId:f.get("connectorId")||null,notes:f.get("notes"),confirm:true});}}><fieldset disabled={busy}><label>Connection<select name="connectorId" defaultValue={v.signalConnectorId||""}><option value="">No register connection</option>{data.signalConnections.map(c=><option key={c.id} value={c.id}>{c.repository.replace(/^companieshouse:/,"")}{c.enabled?"":" · paused"}</option>)}</select></label><label>Explain the legal-entity match or removal<textarea name="notes" required minLength={40} maxLength={1600}/></label><label className={ui.check}><input type="checkbox" required/>I checked the legal entity. Changing this link requires a fresh supplier review.</label><button>Save register link</button></fieldset></form></details>}{d.signalTasks.length>0&&<><h4>Register follow-up</h4><ul>{d.signalTasks.map(t=><li key={t.id}>{t.title} · {t.status} · {t.ownerName}</li>)}</ul><a href="/team">Open assigned work</a></>}</section>
 {v.active&&<><details><summary>Update scope or ownership</summary><p>Saving a change makes existing reviews stale. Open follow-up tasks move to the new owner.</p><VendorForm key={v.version} value={v} members={data.members} busy={busy} save={vendor=>save({action:"UPDATE",version:v.version,vendor})}/></details><details open={!d.reviews.length}><summary>Prepare supplier review</summary><ReviewForm vendor={v} evidence={data.evidence} busy={busy||!!d.signal&&!d.signal.current} signal={d.signal} save={prepare}/>{d.signal&&!d.signal.current&&<p className={ui.warning}>Restore a current observation before preparing a connected supplier review.</p>}</details></>}
 <h3>Review history</h3>{!d.reviews.length&&<p>No review has been prepared.</p>}{d.reviews.map(r=><article key={r.id} className={styles.question}><span className={ui.eyebrow}>{r.status} · {r.recommendation}</span><h3>{r.contextCurrent?"Current evidence and scope":"Historical or changed context"}</h3><small>Prepared {date(r.createdAt)} · valid until {r.validUntil.slice(0,10)} · follow-up due {r.followUpDue.slice(0,10)}</small><p className={styles.prose}>{r.rationale}</p>
 <details><summary>Findings and evidence</summary>{r.signal&&<><h4>Register observation considered in this review</h4><p>{date(r.signal.capturedAt)}</p><ul>{r.signal.observation.checks.map(c=><li key={c.id}>{c.label}: {c.observed} · {c.status}</li>)}</ul></>}{r.assessment.map(c=><div key={c.id}><h4>{VENDOR_CRITERIA.find(x=>x.id===c.id)?.label} · {c.outcome.replaceAll("_"," ")}</h4><p className={styles.prose}>{c.rationale}</p><p>Evidence: {c.evidenceIds.map(id=>r.files.find(f=>f.id===id)?.filename||"Unavailable").join(", ")||"None referenced"}</p></div>)}{r.files.map(f=><p key={f.id}>{f.filename}<code className={styles.hash}>{f.sha256}</code></p>)}<a href="/team/evidence">Inspect evidence in the vault</a></details>
 {r.reviewNotes&&<p className={styles.prose}>Reviewer: {r.reviewNotes}</p>}{r.reviewedAt&&<small>Decision recorded {date(r.reviewedAt)}</small>}
 {v.active&&r.status==="DRAFT"&&<Decision key={r.id+":"+r.version} review={r} userId={userId} busy={busy} save={save}/>}
 {!!r.tasks.length&&<><h4>Owned follow-up</h4><ul className={styles.files}>{r.tasks.map(t=><li key={t.id}><div><strong>{t.title}</strong><span>{t.status.replaceAll("_"," ")}{t.completionException?" · closed by exception":""} · {t.ownerName} · due {t.dueDate.slice(0,10)}</span></div></li>)}</ul><a href="/team">Open team tasks</a><p className={ui.hint}>Completing tasks does not change this decision. A new independent review is needed to change a conditional or rejected outcome.</p></>}
 </article>)}
 {v.active&&<details className={styles.close}><summary>Archive supplier</summary><p>Archiving retains review history and outstanding follow-up tasks.</p><label className={ui.check}><input type="checkbox" checked={archive} onChange={e=>setArchive(e.target.checked)}/>Archive this supplier.</label><button disabled={busy||!archive} onClick={()=>save({action:"ARCHIVE",version:v.version})}>Archive supplier</button></details>}
 </section>;
}
